dtsPropsFor.Button:
/** Button label / content. */
  children: React.ReactNode;
  /** In-app route (renders a router Link; needs a Router in context). */
  to?: string;
  /** External URL (opens in a new tab). */
  href?: string;
  onClick?: (e: React.MouseEvent<HTMLButtonElement | HTMLAnchorElement>) => void;
  /** primary = inverse pill, secondary = outlined pill, text = underlined inline action. @default "primary" */
  variant?: "primary" | "secondary" | "text";
  className?: string;
  /** Native button type (when neither `to` nor `href` is set). @default "button" */
  type?: "button" | "submit" | "reset";
  disabled?: boolean;

dtsPropsFor.EditorialHeading:
/** One entry per visual line; each line is revealed through its own mask. Entries may be JSX. */
  lines: React.ReactNode[];
  /** Heading element. @default "h2" */
  as?: "h1" | "h2" | "h3";
  /** hero = home headline, page = page title, section = section title, card = title inside a card. @default "section" */
  size?: "hero" | "page" | "section" | "card";
  /** Seconds before the first line starts revealing. @default 0 */
  delay?: number;
  className?: string;

dtsPropsFor.FloatingInfoCard:
/** The project to describe (see window.IDEV.projects). */
  project: {
  id: string;
  number: string;
  title: string;
  category: string;
  description: string;
  status: "Completed" | "Ongoing";
  technologies: string[];
  metrics?: { label: string; value: string }[];
  content: {
    overview: string; problem: string; objective: string; solution: string;
    architecture: string; features: string[]; process: string; results: string;
  };
};
  /** card = vertical stack, bar = wide horizontal strip. @default "card" */
  variant?: "card" | "bar";
  /** Heading level for the title. @default "h3" */
  titleAs?: "h2" | "h3";
  /** Slow vertical drift against the scroll (card variant only). @default true */
  drift?: boolean;
  className?: string;

dtsPropsFor.GlassPanel:
children: React.ReactNode;
  /** glass = translucent with blur, solid = opaque raised card. @default "glass" */
  variant?: "glass" | "solid";
  className?: string;

dtsPropsFor.ImageFrame:
/** Media; positioned absolute inset-0 inside the frame's media layer. */
  children: React.ReactNode;
  /** Size the frame here (aspect ratio or height). */
  className?: string;
  /** Tailwind rounded-* classes to override the default corner radius. */
  radius?: string;
  /** Slow scale-down and vertical drift of the media while it crosses the viewport. @default true */
  parallax?: boolean;
  /** Static layer above the media (text, badges); does not scale or drift. */
  overlay?: React.ReactNode;

dtsPropsFor.Logo:
className?: string;
  /** Show only the hexagon mark, without the wordmark. @default false */
  iconOnly?: boolean;

dtsPropsFor.Marquee:
/** Short labels to loop. */
  items: string[];
  /** Scroll speed. @default "medium" */
  speed?: "slow" | "medium" | "fast";
  className?: string;

dtsPropsFor.PageHeader:
/** Mono caps label above the heading, e.g. "OUR PORTFOLIO". */
  eyebrow: string;
  /** Heading lines (page size, rendered as the page's h1). */
  lines: React.ReactNode[];
  /** Intro paragraph set in the right-hand column on wide screens. */
  description?: React.ReactNode;

dtsPropsFor.Section:
id?: string;
  className?: string;
  children: React.ReactNode;

dtsPropsFor.SectionHeader:
/** Mono caps label, e.g. "02 // WHAT WE BUILD". */
  eyebrow: string;
  /** Heading lines; each slides up out of a mask. */
  lines: React.ReactNode[];
  /** @default "h2" */
  as?: "h1" | "h2";
  /** @default "section" */
  size?: "hero" | "page" | "section" | "card";
  /** Supporting copy, right-hand column on wide screens. */
  description?: React.ReactNode;
  /** Optional trailing element (e.g. a link) under the description. */
  action?: React.ReactNode;
  /** Replaces the default bottom margin (mb-16 sm:mb-24). */
  className?: string;

dtsPropsFor.ProjectMetrics:
/** Key figures, e.g. a project's `metrics`. */
  metrics: { label: string; value: string }[];
  /** Hero-scale figures for a project page. @default false */
  large?: boolean;
  className?: string;

dtsPropsFor.ProjectPreview:
/** One of the seven project ids: ss-agencies, fintech-startup, smart-traffic, receipt-processing, internal-developer-platform, iot-monitoring, direct-market-access. */
  id: string;
  /** Extra classes for the stage, e.g. bottom padding to clear an overlapping panel. */
  className?: string;

dtsPropsFor.ProjectShowcase:
/** The project to present (see window.IDEV.projects). */
  project: {
  id: string;
  number: string;
  title: string;
  category: string;
  description: string;
  status: "Completed" | "Ongoing";
  technologies: string[];
  metrics?: { label: string; value: string }[];
  content: {
    overview: string; problem: string; objective: string; solution: string;
    architecture: string; features: string[]; process: string; results: string;
  };
};
  /** Position in the list; selects one of four compositions (index % 4). */
  index: number;
  /** Heading level for the project title. @default "h3" */
  titleAs?: "h2" | "h3";

dtsPropsFor.ScrollReveal:
children: React.ReactNode;
  /** Edge the content travels in FROM. @default "up" */
  direction?: "up" | "down" | "left" | "right" | "none";
  /** Seconds. @default 0 */
  delay?: number;
  /** Seconds. @default 0.9 */
  duration?: number;
  /** Travel distance in px. @default 36 */
  distance?: number;
  className?: string;

dtsPropsFor.TechChips:
/** Technology names, shown as-is. */
  technologies: string[];
  className?: string;

dtsPropsFor.ViewCaseStudyLink:
/** Project id; links to /work/<id>. */
  id: string;
  className?: string;
